import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"MagicDrive-V2: High-Resolution Long Video Generation for Autonomous Driving with Adaptive Control","description":"","frontmatter":{"title":"MagicDrive-V2: High-Resolution Long Video Generation for Autonomous Driving with Adaptive Control","arxiv":"2411.13807","date":"2024-11-21","authors":"Ruiyuan Gao, Kai Chen, Bo Xiao, Lanqing Hong, Zhenguo Li, Qiang Xu","categories":"cs.CV","topics":"世界模型, 自动驾驶视频生成, 时空条件编码","outline":[2,2]},"headers":[],"relativePath":"papers/2411.13807.md","filePath":"papers/2411.13807.md","lastUpdated":null}'),l={name:"papers/2411.13807.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="magicdrive-v2-high-resolution-long-video-generation-for-autonomous-driving-with-adaptive-control" tabindex="-1">MagicDrive-V2: High-Resolution Long Video Generation for Autonomous Driving with Adaptive Control <a class="header-anchor" href="#magicdrive-v2-high-resolution-long-video-generation-for-autonomous-driving-with-adaptive-control" aria-label="Permalink to &quot;MagicDrive-V2: High-Resolution Long Video Generation for Autonomous Driving with Adaptive Control&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2411.13807" target="_blank" rel="noreferrer">2411.13807</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-11-21（v4: 2025-07-25，ICCV 2025 camera-ready）</td></tr><tr><td><strong>作者</strong></td><td>Ruiyuan Gao, Kai Chen, Bo Xiao, Lanqing Hong, Zhenguo Li, Qiang Xu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>3D VAE 把时间轴压掉后逐帧几何条件与 latent 对不齐，本文用与 VAE 同倍率的时序下采样编码器重新对齐条件，再配 MVDiT 与三阶段混分辨率训练，把可控多视角驾驶视频推到 848×1600×6×241 帧。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>要生成可用于自动驾驶闭环仿真的街景视频，三件事必须同时满足：分辨率足够高（远处小目标才可辨认）、帧数足够多（才能构成有意义的交互场景）、几何条件精确可控（每一帧的 3D 框、路网、自车轨迹都要被严格遵守）。此前的方法在前两项上被卡死：论文 Table 1 列出的多视角方法中，MagicDrive 是 224×400×6 的 60 帧，Drive-WM、Panacea、DriveDreamer2 都只有 8 帧，Delphi 10 帧，DiVE 16 帧。</p><p>价值在于数据引擎与策略测试。感知模型训练需要海量带标注街景，闭环策略评测需要长时段可控 rollout，而真实采集既贵又覆盖不到危险场景。分辨率与帧数一旦上去，生成数据才真正能替代或补充采集数据。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>MagicDrive 与 MagicDrive3D 已经把 3D 框、BEV 路网图、自车轨迹、相机位姿整合进多视角街景合成，控制质量足够好，是本文的主 baseline。BEVControl、Drive-WM、Panacea、DriveDreamer2、Delphi、DiVE 各自在多视角一致性或控制信号种类上有推进。GAIA-1、Vista、DriveDreamer 则走前视单目路线。</p><p>它们不够用的原因分两层。表层是规模：这些方法基于 2D VAE 加 UNet，序列长度随帧数线性增长，显存直接封死了分辨率与帧数的上限。深层原因才是本文真正的切入点——<strong>换成 3D VAE 就能解决显存，但换了之后几何控制会失效</strong>。2D VAE 时代，latent 的时间轴与视频帧一一对应，因此图像域的控制方法（ControlNet 式加性编码）可以原样搬到视频上；3D VAE 做了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 倍时序压缩，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 帧只剩 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 个 latent，逐帧条件与 latent 不再对齐，既有控制模块直接不可用。论文 Figure 2 就是在讲这件事。</p><p>作者还试过更省事的路：先用 Open-Sora 1.2 的 VAE 与预训练扩散模型微调，结果图像质量与可控性都不如 MagicDrive，附录 J 把原因归给 VAE 重建能力不足与文生视频先验的泛化局限，于是改为用 CogVAE 从零训练扩散模型。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有事实：DiT 的 Gflops 与 FID 呈良好相关，比 UNet 更适合放大；3D VAE 在时空两个方向压缩，把序列长度砍掉一个量级；序列并行可以突破单卡显存。这三条合起来说明&quot;高分辨率长视频&quot;在工程上已经可行。</p><p>障碍出现在把控制接进去的那一刻。最省事的做法是照抄文本条件的处理方式——把逐帧条件在时间维上聚合成 1，再重复 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 次。作者试了，结果出现拖影（论文称 trailing issues，Figure 10 里的 &quot;Box Reduce&quot;），并推测是 repeat 操作造成的：所有 latent 拿到的是同一份&quot;平均条件&quot;，模型无从知道物体在这 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 帧内往哪走。</p><p>到这一步答案就浮出来了：既然错配是 3D VAE 的时序下采样造成的，那就让条件编码器<strong>用同样的下采样方式</strong>走一遍，而不是先塌成 1 再摊开。剩下的问题是训练成本——直接训高分辨率长视频每步要几分钟，于是用渐进式：先低分辨率图像快速学控制，再高分辨率短视频，最后长视频。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>3D VAE 让视频 latent 变短了，但几何条件没跟着变短，两者的时间轴对不上。把条件在时间上&quot;求平均再复制&quot;会抹掉帧间差异，物体轨迹就糊成拖影。正确做法是让条件走一遍与 VAE 完全相同的时序下采样，使每个 latent 拿到的是它自己那几帧的条件而非全局平均。对齐了，控制就回来了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 nuScenes 验证集里一个&quot;雨天城市路口，6 路环视，241 帧&quot;的条件为例：</p><ul><li><strong>输入</strong>：帧描述序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1401em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathbf">C</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">L</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathbf">Tr</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8901em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.139em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，含相机位姿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathbf">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>、BEV 路网图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（8 类语义）、3D 框 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（10 类目标）、文本 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">L</span></span></span></span>、自车轨迹 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1371em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord"><span class="mord mathbf">Tr</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8901em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.139em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>。除轨迹外全部参数化在自车 LiDAR 坐标系下。</li><li><strong>文本增强</strong>：nuScenes 原生描述只有晴/雨、昼/夜，太贫瘠。作者用多模态大模型对每段视频的<strong>中间一帧</strong>重新生成描述，只补充道路类型、建筑树木等背景信息，刻意不描述动态与目标类别，以免与几何条件冲突。</li><li><strong>架构</strong>：以 STDiT-3 为基本块，加入 MVDiT——即插入跨视角注意力层保证 6 路视图一致；文本、框、相机、轨迹走 cross-attention，路网图走 ControlNet 式加性分支。</li><li><strong>时空条件编码（核心）</strong>：路网图是网格数据，直接在 ControlNet 分支里加入与 3D VAE 同构的时序下采样模块；3D 框先对不可见框做 padding 使各视角各帧序列等长，再用带 RoPE 的时序 transformer 做下采样，得到与 latent 对齐的时空嵌入；自车轨迹复用框编码器，只把框 MLP 换成相机位姿 MLP。所有下采样倍率与 VAE 对齐，即输入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span><span class="mord mathnormal">n</span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 帧、输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal">n</span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 个 latent。</li><li><strong>训练</strong>：三阶段。Stage 1 在 224×400 图像上 80,000 步；Stage 2 混入 224×400 与 424×800 的 9/17/33/65 帧视频 40,000 步；Stage 3 引入 848×1600 与全长视频、序列并行度 4，训练 30,000 步。32 张 A800，Adam，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，最后两阶段带 3000 步线性 warm-up。</li><li><strong>推理</strong>：Rectified Flow 采样 30 步，CFG 尺度 2.0；训练时以 15% 概率随机丢弃文本、相机、轨迹、框的嵌入以支持 CFG，路网图的空条件取全零。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>模型用 Rectified Flow 而非标准 DDPM。它的想法是：与其学一条弯弯曲曲的去噪轨迹，不如直接把噪声 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 与数据 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 用一条直线连起来，让网络学这条直线的方向。插值定义为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϵ</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是视频经 VAE 得到的 latent，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6542em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时是纯噪声，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 时是干净 latent，中间是线性混合。训练目标是让网络 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">Θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 预测这条直线的速度：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.3092em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ϵ</span><span class="mrel mtight">∼</span><span class="mord mathcal mtight" style="margin-right:0.1474em;">N</span><span class="mopen mtight">(</span><span class="mord mtight">0</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">Θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">ϵ</span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">∥</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>直觉是：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span> 就是从噪声指向数据的那个向量，网络只要在任意中间点上把这个方向说对，推理时沿着预测方向走就能到达数据。轨迹越直，需要的采样步数越少——这也是本文只用 30 步就能出图的原因。时间步按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">lognorm</span></span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span> 采样，把训练算力更多分配到中间噪声水平。</p><p>条件对齐这一侧没有新的推导，关键约束是纯离散的：条件编码器的时序下采样必须满足输入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span><span class="mord mathnormal">n</span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>、输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal">n</span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，与 CogVAE 的压缩倍率逐位匹配。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：分辨率与帧数上去之后，质量与可控性到底如何？</strong> 在 nuScenes 上与 MagicDrive 系列对比（Table 2，只取前 16 帧评测）：FVD 从 MagicDrive(16f) 的 218.12、MagicDrive(60f) 的 217.94、MagicDrive3D 的 210.40 降到 94.84；BEVFormer 测得的 mAP 从 11.86/11.49/12.05 升到 18.17，mIoU 从 18.34/18.27/18.27 升到 20.40。结论是三项全面改善。图像任务上（Table 3）FID 反而略差于 MagicDrive（20.91 vs 16.20），但车辆 mIoU 32.73 vs 27.01、mAP 17.65 vs 12.30 明显更好——即质量小退、可控性大进。</p><p><strong>问题二：时空条件编码是不是真的必要？</strong> 与两个 baseline 比：全局时序缩减（Reduce）和时序插值（Interp.）。16 样本过拟合实验里 4× 下采样收敛最快、最终验证损失最低（Figure 9）；可视化上（Figure 10）Reduce 会产生伪影与轨迹拖影，本文方法保持目标清晰与运动正确。</p><p><strong>问题三：混分辨率混长度训练值不值？</strong> Table 4 的四组配置显示：只用低分辨率短视频最差（FVD 97.21、mAP 10.17、mIoU 12.42）；加入长视频主要提升可控性；加入高分辨率则三项齐升。混长度会让 FVD 略微变差（96.34→99.66），但换来了长度外推能力，作者判定这个交易划算。</p><p><strong>问题四：能外推多远？</strong> 训练最长为 33×848×1600 与 241×224×400，推理却能出 241×848×1600（nuScenes 的满分辨率满长度，约为训练样本长度的 8 倍）。Table 5 用逐 16 帧 FVD 检验：424×800 下首 16 帧 530.65、第 2 段 562.99；848×1600 下 559.70/573.46/583.50/585.89，随外推缓慢上升但没有崩塌。作为对照，附录 K 把 Vista 的 4 次 rollout 与本文的单次推理放在一起比，rollout 的质量衰减肉眼可见。</p><p><strong>问题五：能否迁移？</strong> 在 Waymo 上微调一天（1k+ 步）即可生成 3 视角视频；混合 Waymo 与 nuScenes 训练后，FVD 分别达到 105.17 与 74.30，后者优于 Table 2 的 94.84。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话</strong>：3D VAE 把视频 latent 在时间上压缩 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 倍，导致逐帧几何条件与 latent 错位，既有的街景可控生成方法直接失效；把条件在时间维塌成 1 再重复的朴素修法会产生轨迹拖影；本文让条件编码器复用与 VAE 同倍率的时序下采样，恢复了逐 latent 的精确控制；配合 MVDiT 跨视角注意力与&quot;图像→高分短视频→长视频&quot;的三阶段混合训练，模型在 nuScenes 上把 FVD 从 218 降到 94.84、mAP 从 11.86 升到 18.17；混长度混分辨率训练还带来了 8 倍的长度外推能力，可一次性生成 241×848×1600×6 的视频而无需 rollout。</p><p><strong>三句话</strong>：换用 3D VAE 是长视频生成的必经之路，但它会打断几何条件与 latent 的时间对齐。MagicDrive-V2 用与 VAE 同构的时序下采样把条件重新对齐，从而在 3.3 倍分辨率、4 倍帧数下仍保持精确控制。渐进式混合训练让模型学会在训练配置之外外推长度，避免了 rollout 的误差累积。</p><p><strong>一句话</strong>：条件编码器必须和 VAE 用同一套时序压缩，否则 3D VAE 带来的效率红利要用可控性来偿还。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>长度外推得到的视频，其质量退化足够缓慢，以至于外推段仍可用于下游任务</strong>。整篇论文最亮眼的卖点——241 帧满分辨率生成——完全依赖于它；若不成立，模型的实际可用长度就退回训练时的 33 帧，与前人的差距被大幅压缩。</p><p>它在实践中可能不成立，原因是论文提供的证据只有 FVD 这一个指标，而 FVD 度量的是分布层面的视觉真实度，对<strong>几何控制的缓慢漂移不敏感</strong>。一辆车在第 200 帧偏离标注框两米，画面仍然自然，FVD 几乎不会惩罚。而 Table 2 里衡量可控性的 mAP/mIoU 只在前 16 帧上计算，Table 5 的外推实验只报了 FVD。也就是说，论文没有给出&quot;外推段的 mAP/mIoU 是否保持&quot;的直接证据。作者提供的支持性证据是间接的：Figure 8 用同色框标注同一目标供人工核对，附录 G 做了人类一致性评测（但比较对象是 MagicDrive 而非长短段自比）。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现整套系统，只检验 §9 那条假设：</p><ul><li>数据：nuScenes 验证集里取 10 段 241 帧序列的官方标注（3D 框 + 路网）。</li><li>实现：使用作者开源的 MagicDrive-V2 权重，在 424×800、6 视角下一次性生成 129 帧。</li><li>测量：把生成视频按 16 帧切段，对<strong>每一段</strong>分别跑 BEVFormer，计算 mAP 与 BEV mIoU，画出随段索引的曲线；同时按论文方式计算逐段 FVD 作为对照。</li><li>判据：若 mAP 从第 1 段到第 8 段的相对下降小于 10%，支持&quot;外推段可用&quot;；若 FVD 只涨了 10% 而 mAP 掉了 30% 以上，就证明 FVD 掩盖了控制漂移，论文的外推 claim 需要限定在&quot;视觉质量&quot;而非&quot;可控性&quot;上。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给 FVD 的改善提供<strong>替代解释</strong>：94.84 vs 218.12 这个巨大差距，可能主要来自分辨率与架构（DiT + CogVAE）的升级，而非时空条件编码这一核心贡献。设计一个受控实验：保持 STDiT-3 骨干、CogVAE、渐进训练全部不变，只把时空条件编码换成论文批评的 Reduce 基线，训练到相同 GPU 小时，然后报告完整的 FVD/mAP/mIoU。如果 FVD 仍在 100 附近而只有 mAP/mIoU 明显下降，那么&quot;3D VAE 破坏几何控制&quot;这个论述成立，但它解释的是可控性而非 Table 2 里最醒目的 FVD 提升——论文正文把两者放在一起呈现，容易让读者把功劳归错地方。论文的过拟合实验（Figure 9）只在 16 个样本上比验证损失，尚不足以撑起这个区分。</p><p>第二条攻击针对可预测的失败条件：nuScenes 的 12Hz 标注是用 ASAP 从 2Hz 插值出来的，论文自己承认&quot;插值结果并不完全准确&quot;。构造一批包含<strong>急动态</strong>的场景（横穿行人、切入车辆、急刹），此时插值标注与真实位置偏差最大。若模型在这些片段上的控制精度显著劣于平稳直行片段，说明模型学到的与其说是&quot;遵守 3D 框&quot;，不如说是&quot;遵守平滑运动先验&quot;——而急动态恰恰是仿真最需要的场景。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：MagicDrive-V2 的条件是<strong>外生</strong>的——3D 框和轨迹由数据集给定，模型只负责渲染。这意味着它能生成&quot;标注长什么样&quot;的视频，却不能回答&quot;如果自车这样开，别的车会怎么反应&quot;。附录 D 显示 6 视角 241 帧要 28.92 分钟，闭环仿真所需的交互式 rollout 在这个成本下无从谈起。</p><p><strong>新的 framing</strong>：把几何条件从&quot;输入&quot;改成&quot;与视频联合建模的变量&quot;，即同时生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathbf">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathbf">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，并让自车轨迹作为唯一的外生控制。这不是加模块，而是换目标：模型要学的是场景的<strong>联合演化分布</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathbf">Tr</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">M</span><span class="mclose">)</span></span></span></span>，其中他车行为对自车动作有响应。可借鉴的相邻领域工具是轨迹预测里的联合多智能体模型（如场景级 anchor 与交互式解码），以及扩散模型中的分层生成——先在低维的框空间做快速采样，再把视频作为条件渲染层。</p><p><strong>第一个实验</strong>：在 nuScenes 上训练一个轻量的框序列扩散模型，条件为路网 + 自车轨迹，生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathbf">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>；把它的输出直接喂给现成的 MagicDrive-V2 作为条件。评测方式是反事实一致性：对同一初始场景给出两条差异明显的自车轨迹（正常通过 vs 急刹），检查生成的他车框序列是否出现可测量的差异（例如后车跟车距离的分布位移）。如果差异显著且符合交通常识，说明&quot;框空间快、像素空间慢&quot;的分层结构可以把交互能力和渲染质量解耦——这正是把驾驶视频生成器变成可闭环仿真器所缺的一块。</p>',49)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
